// A text search for a code symbol (grep, rg, ag, git grep, sed or awk), in code a
// language server covers: the search runs as asked, and Claude is told which LSP
// call answers it exactly. A nudge, never a block.

/**
 * The languages a language server reads, by file extension: the server the warm-up starts
 * once per `kind`, and the language's name as the person knows it. The extensions are those
 * the servers' plugins claim (the official ones, and lsp-plus's own).
 */
export const LANGUAGES: ReadonlyArray<{ exts: readonly string[]; kind: string; name: string }> = [
  { exts: ['ts', 'tsx', 'js', 'jsx', 'mjs', 'cjs', 'mts', 'cts'], kind: 'ts', name: 'TypeScript/JavaScript' },
  { exts: ['py', 'pyi'], kind: 'py', name: 'Python' },
  { exts: ['c', 'h', 'cc', 'cpp', 'cxx', 'hpp', 'hh', 'hxx'], kind: 'c', name: 'C/C++' },
  { exts: ['rs'], kind: 'rs', name: 'Rust' },
  { exts: ['go'], kind: 'go', name: 'Go' },
  { exts: ['swift'], kind: 'swift', name: 'Swift' },
  { exts: ['java'], kind: 'java', name: 'Java' },
  { exts: ['kt', 'kts'], kind: 'kt', name: 'Kotlin' },
  { exts: ['cs'], kind: 'cs', name: 'C#' },
  { exts: ['php'], kind: 'php', name: 'PHP' },
  { exts: ['rb', 'rake', 'gemspec', 'ru'], kind: 'rb', name: 'Ruby' },
  { exts: ['lua'], kind: 'lua', name: 'Lua' },
  { exts: ['sh', 'bash'], kind: 'sh', name: 'shell' },
  { exts: ['tf', 'tfvars'], kind: 'tf', name: 'Terraform' },
]

/** Source files a language server reads. */
export const LSP_FILES = new RegExp(`\\.(${LANGUAGES.flatMap(l => l.exts).join('|')})$`)

const SEARCHERS = /^(?:grep|egrep|fgrep|rg|ag|ack)$/
const DEF_WORDS = '(?:def|function|class|fn|func|fun|const|let|var|val|interface|type|struct|enum|trait|protocol|object|module)'
// What may stand between the keyword and the name: Go's receiver `func (s *Server) Name`, Kotlin's
// type parameters and receiver type `fun <T> List<T>.name`, Ruby's `def self.name`.
const RECEIVER = '(?:\\([^)]*\\)\\s*|<[^>]*>\\s*)?(?:[\\w$]+(?:<[^>]*>)?\\??\\.)?'

export type SymbolSearch = { name: string; kind: 'uses' | 'definition' }

/** Splits a shell command line into words, honouring quotes; enough for a grep's arguments. */
function words(segment: string): string[] {
  const out: string[] = []
  for (const m of segment.matchAll(/'([^']*)'|"((?:[^"\\]|\\.)*)"|(\S+)/g)) out.push(m[1] ?? m[2]?.replace(/\\(.)/g, '$1') ?? (m[3] as string))
  return out
}

/** The pattern a sed or awk program searches for: `sed -n '/name/p'`, `awk '/name/ {...}'`. */
function scriptPattern(tool: string, args: string[]): string | undefined {
  for (const a of args) {
    if (a.startsWith('-')) continue
    const m = tool === 'sed' ? /^\/(.+?)\/(?:p|=)$/.exec(a) : /^\/(.+?)\/(?:\s*\{.*\})?$/s.exec(a)
    return m?.[1]
  }
  return undefined
}

/** The pattern of one grep-like command, past its options and the values they take. */
function grepPattern(args: string[]): string | undefined {
  for (let i = 0; i < args.length; i++) {
    const a = args[i] as string
    if (a === '-e' || a === '--regexp') return args[i + 1]
    if (/^--?[A-Za-z]/.test(a)) {
      if (/^(-[ABCmfgtT]|--(include|exclude|exclude-dir|glob|type|type-add|max-count|context|after-context|before-context))$/.test(a)) i++
      continue
    }
    return a
  }
  return undefined
}

/**
 * The pattern of each command of the line that searches files: after `cd …&&`,
 * behind `xargs`, in a pipeline; grep, egrep, rg, ag, ack, git grep, and sed or
 * awk printing what matches.
 */
export function searchPatterns(command: string): string[] {
  const patterns: string[] = []
  // Each command of the line; in a pipeline only its head or an xargs stage reads files (a grep fed by a pipe filters text).
  const stages = command
    .split(/\s*(?:&&|\|\||;)\s*/)
    .flatMap(cmd => cmd.split(/\s*\|\s*/).filter((stage, i) => i === 0 || /^xargs\b/.test(stage.trim())))
  for (const raw of stages) {
    let args = words(raw.trim())
    if (args[0] === 'xargs') {
      // xargs' own options (and the values of -n, -I, -P, -L, -s, -d) come before the command it runs.
      let i = 1
      while (i < args.length && (args[i] as string).startsWith('-')) i += /^-[nIPLsd]$/.test(args[i] as string) ? 2 : 1
      args = args.slice(i)
    }
    const tool = args[0] ?? ''
    let pattern: string | undefined
    if (tool === 'git' && args[1] === 'grep') pattern = grepPattern(args.slice(2))
    else if (SEARCHERS.test(tool)) pattern = grepPattern(args.slice(1))
    else if ((tool === 'sed' && args.includes('-n')) || tool === 'awk') pattern = scriptPattern(tool, args.slice(1))
    if (pattern !== undefined) patterns.push(pattern)
  }
  return patterns
}

/**
 * Whether a shell command searches for one code symbol. Its pattern must name
 * one identifier (bare, `-w`, `\bname\b`, `name(`, `.name`) or its definition
 * (`def name`, `function name`); alternations and free text are not symbols.
 */
export function symbolSearch(command: string): SymbolSearch | undefined {
  for (const pattern of searchPatterns(command)) {
    const found = asSymbol(pattern)
    if (found !== undefined) return found
  }
  return undefined
}

function asSymbol(pattern: string): SymbolSearch | undefined {
  const p = pattern.replace(/\\b|\\<|\\>/g, '').replace(/^\^\s*/, '')
  const def = new RegExp(`^(?:export\\s+)?${DEF_WORDS}\\s+(?:\\\\?\\([^)]*\\)\\s*)?(?:[\\w$]+\\\\?\\.)?([A-Za-z_$][\\w$]*)\\b`).exec(p)
  if (def) return { name: def[1] as string, kind: 'definition' }
  const use = /^\.?([A-Za-z_$][\w$]*)(?:\\?\(|\s*\\?\()?$/.exec(p)
  if (use && (use[1] as string).length >= 3) return { name: use[1] as string, kind: 'uses' }
  return undefined
}

export type Hit = { path: string; line: number; text: string }

/** `path:line:text` rows of a grep's output (with -n), only in files a language server reads. */
export function codeHits(output: string): Hit[] {
  const hits: Hit[] = []
  for (const row of output.split('\n')) {
    const m = /^([^\s:]+):(\d+):(.*)$/.exec(row)
    if (m && LSP_FILES.test(m[1] as string)) hits.push({ path: m[1] as string, line: Number(m[2]), text: m[3] as string })
  }
  return hits
}

/**
 * Whether a source line uses `name` as code: outside its string literals and a
 * trailing comment. A name met only in strings (a mod's name in a message, a
 * key) is no symbol to ask the language server about.
 */
export function usesAsCode(text: string, name: string): boolean {
  const code = text.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, '""').replace(/(^|\s)(#|\/\/).*$/, '')
  return new RegExp(`(^|[^\\w$])${name.replace(/\$/g, '\\$')}(?![\\w$])`).test(code)
}

/** Among the hits, where `name` is defined, at the column the LSP tool asks for (1-based). */
export function definitionAt(hits: readonly Hit[], name: string): { path: string; line: number; character: number } | undefined {
  const re = new RegExp(`\\b${DEF_WORDS}\\s+${RECEIVER}(${name.replace(/\$/g, '\\$')})\\b`)
  for (const h of hits) {
    const m = re.exec(h.text)
    if (m) return { path: h.path, line: h.line, character: m.index + m[0].length - name.length + 1 }
  }
  return undefined
}

/**
 * The note: what the language server answers better, the exact call, and what
 * it cannot see, so grep keeps that part. It adds a way; it takes none away.
 *
 * With the cells mod's run_cell in the session, the note also names the call
 * there: refs() asks the server without the LSP tool loaded first (it is
 * deferred) and gives each place with its line, and rename() renames every
 * code reference through Edit. `file` is a file that uses the name, for when
 * the definition is not among the hits.
 */
export function nudge(
  search: SymbolSearch,
  at: { path: string; line: number; character: number } | undefined,
  again: boolean,
  cells: { file?: string } | undefined = undefined,
): string {
  const where = at ? `LSP findReferences on ${at.path}:${at.line}:${at.character}` : `LSP workspaceSymbol with query "${search.name}"`
  const cell = cells === undefined ? undefined : at ? `refs('${at.path}', '${search.name}', { line: ${at.line} })` : cells.file ? `refs('${cells.file}', '${search.name}')` : undefined
  if (again) {
    const or = cell ? ` (or ${cell} in run_cell)` : ''
    return `\`${search.name}\`: ${where}${or} gives its exact code uses; grep stays needed for strings, docs and dynamic uses.`
  }
  const what = at
    ? 'lists exactly its uses in the code, without comments, strings or namesakes, and incomingCalls there lists the functions that call it'
    : 'finds its definition, and findReferences there lists exactly its uses in the code'
  const note = `\`${search.name}\` is a code symbol in files a language server covers: ${where} ${what}. The server does not see strings, dynamic uses or most docs, so for a rename or a complete sweep keep the grep for those.`
  if (cell === undefined) return note
  return `${note} In run_cell, ${cell} asks the same in one step without loading the LSP tool, each place with its line; rename(path, name, newName) there renames every code reference through Edit and lists where the name is left as text.`
}

files.hooks/answer.ts:
// The language server's answer to a symbol grep, attached to the grep's own result: the
// functions that call it, or its references, read from the server by the hook itself. No
// advice and no second step for Claude: the exact code answer is already there, and grep's
// output stays for what the server cannot see (strings, comments, docs, namesakes).

/** One place the server lists: a caller (with the lines it calls from) or a reference line. */
export type Caller = { file: string; name: string; kind: string; line: number; at: number[] }

/** `incomingCalls` text: `file:` headers, then `  name (Kind) - Line N [calls at: L:C, …]`. */
export function parseIncoming(text: string): Caller[] {
  const out: Caller[] = []
  let file = ''
  for (const row of text.split('\n')) {
    const header = /^(\S.*):$/.exec(row)
    if (header && !row.startsWith('Found')) {
      file = header[1] as string
      continue
    }
    const m = /^\s+(\S+) \((\w+)\) - Line (\d+)(?: \[calls at: ([^\]]*)\])?/.exec(row)
    if (m && file) {
      const at = (m[4] ?? '').split(',').map(s => Number(s.trim().split(':')[0])).filter(n => n > 0)
      out.push({ file, name: m[1] as string, kind: m[2] as string, line: Number(m[3]), at })
    }
  }
  return out
}

/** `findReferences` text: `file:` headers, then `  Line L:C` rows (or `file:L:C` for a single one). */
export function parseReferences(text: string): Array<{ file: string; line: number }> {
  const out: Array<{ file: string; line: number }> = []
  let file = ''
  for (const row of text.split('\n')) {
    const single = /^\s+(\S+?):(\d+):(\d+)$/.exec(row)
    if (single) {
      out.push({ file: single[1] as string, line: Number(single[2]) })
      continue
    }
    const header = /^(\S.*):$/.exec(row)
    if (header && !row.startsWith('Found')) {
      file = header[1] as string
      continue
    }
    const m = /^\s+Line (\d+):\d+/.exec(row)
    if (m && file) out.push({ file, line: Number(m[1]) })
  }
  return out
}

/** `documentSymbol` text, as a tree by indentation: each symbol with the names of those it sits in. */
export function parseOutline(text: string): Array<{ name: string; kind: string; line: number; path: string[] }> {
  const out: Array<{ name: string; kind: string; line: number; path: string[] }> = []
  const stack: Array<{ depth: number; name: string }> = []
  for (const row of text.split('\n')) {
    const m = /^(\s*)(\S+) \((\w+)\) - Line (\d+)/.exec(row)
    if (!m) continue
    const depth = (m[1] as string).length
    while (stack.length > 0 && (stack.at(-1) as { depth: number }).depth >= depth) stack.pop()
    out.push({ name: m[2] as string, kind: m[3] as string, line: Number(m[4]), path: stack.map(s => s.name) })
    stack.push({ depth, name: m[2] as string })
  }
  return out
}

/** A caller's qualified name from its file's outline: `Class.method`, `outer.inner`; its plain name when not found. */
export function qualified(outline: ReturnType<typeof parseOutline>, name: string, line: number): string {
  const hit = outline.find(s => s.name === name && s.line === line)
  return hit ? [...hit.path, name].join('.') : name
}

const MAX_CHARS = 1600

/**
 * The note: the server's callers (qualified, with their call lines) or references, by file,
 * compact and capped. It says what it covers, so grep's output keeps its part.
 */
export function answerNote(
  name: string,
  found: { callers: Array<Caller & { qualified: string }> } | { references: Array<{ file: string; line: number }> },
): string {
  const rows: string[] = []
  let head: string
  if ('callers' in found) {
    const files = [...new Set(found.callers.map(c => c.file))]
    head = `\`${name}\` per the language server: called from ${found.callers.length} function${found.callers.length === 1 ? '' : 's'} in ${files.length} file${files.length === 1 ? '' : 's'}`
    for (const f of files) {
      const here = found.callers.filter(c => c.file === f).map(c => `${c.qualified} (${c.at.join(', ')})`)
      rows.push(`${f}: ${here.join(', ')}`)
    }
  } else {
    const files = [...new Set(found.references.map(r => r.file))]
    head = `\`${name}\` per the language server: ${found.references.length} reference${found.references.length === 1 ? '' : 's'} in code, in ${files.length} file${files.length === 1 ? '' : 's'}`
    for (const f of files) rows.push(`${f}: ${found.references.filter(r => r.file === f).map(r => r.line).join(', ')}`)
  }
  const tail = '(code only: strings, comments, docs and namesakes are in the grep above)'
  let body = ''
  let shown = 0
  for (const row of rows) {
    if (body.length + row.length > MAX_CHARS) break
    body += `\n${row}`
    shown++
  }
  const more = shown < rows.length ? `\n… and ${rows.length - shown} more files` : ''
  return `${head} ${tail}:${body}${more}`
}

/** Whether an answer looks like a server still indexing: it knows only the file it was asked about. */
export function looksCold(files: readonly string[], grepFiles: readonly string[], asked: string): boolean {
  const others = grepFiles.filter(f => f !== asked)
  return others.length > 0 && files.every(f => f === asked)
}

files.hooks/terraform.ts:
// Terraform names what it declares by address: var.region, local.tags, module.vpc,
// aws_s3_bucket.logs, data.aws_iam_policy_document.read. A grep for an address, or for the
// block that declares it, gets terraform-ls's references. A block is seen only within its
// module, the directory it is in, so the server is asked at each declaration in a directory
// where the grep found the address.

export type TfSearch = {
  /** The address as the configuration writes it. */
  address: string
  /** The declaring line, as an extended regular expression for git grep. */
  declares: string
  /** The name in the declaring line the server is asked about. */
  label: string
}

const ID = '[A-Za-z_][A-Za-z0-9_-]*'

/** The address a grep's pattern names, from a use (`var.region`) or its declaration (`variable "region"`). */
export function tfAddress(pattern: string): TfSearch | undefined {
  const p = pattern
    .replace(/\\b|\\<|\\>/g, '')
    .replace(/\\([."])/g, '$1')
    .replace(/^\^\s*/, '')
    .trim()
  const block = (kind: string, ...labels: string[]) => `^[[:space:]]*${kind}[[:space:]]+${labels.map(l => `"${l}"`).join('[[:space:]]+')}`
  let m: RegExpExecArray | null
  if ((m = new RegExp(`^var\\.(${ID})$`).exec(p)) || (m = new RegExp(`^variable\\s+"(${ID})"`).exec(p))) {
    const name = m[1] as string
    return { address: `var.${name}`, declares: block('variable', name), label: name }
  }
  if ((m = new RegExp(`^module\\.(${ID})$`).exec(p)) || (m = new RegExp(`^module\\s+"(${ID})"`).exec(p))) {
    const name = m[1] as string
    return { address: `module.${name}`, declares: block('module', name), label: name }
  }
  if ((m = new RegExp(`^local\\.(${ID})$`).exec(p))) {
    const name = m[1] as string
    return { address: `local.${name}`, declares: `^[[:space:]]*${name}[[:space:]]*=`, label: name }
  }
  if ((m = new RegExp(`^data\\.(${ID})\\.(${ID})$`).exec(p)) || (m = new RegExp(`^data\\s+"(${ID})"\\s+"(${ID})"`).exec(p))) {
    const [type, name] = [m[1] as string, m[2] as string]
    return { address: `data.${type}.${name}`, declares: block('data', type, name), label: name }
  }
  // A resource type is the provider's name, an underscore and the kind: aws_s3_bucket.
  if ((m = new RegExp(`^([a-z][a-z0-9]*_[A-Za-z0-9_]+)\\.(${ID})$`).exec(p)) || (m = new RegExp(`^resource\\s+"(${ID})"\\s+"(${ID})"`).exec(p))) {
    const [type, name] = [m[1] as string, m[2] as string]
    return { address: `${type}.${name}`, declares: block('resource', type, name), label: name }
  }
  return undefined
}

export const TF_FILES = /\.tf$/

/** The directory a repository path is in ('' at the root). */
export function dirOf(path: string): string {
  const i = path.lastIndexOf('/')
  return i < 0 ? '' : path.slice(0, i)
}

/** Whether a line of a .tf file sits in a `locals` block: the block it is in starts at the last unindented line above. */
export function inLocals(lines: readonly string[], line: number): boolean {
  for (let i = line - 2; i >= 0; i--) {
    const row = lines[i] as string
    if (/^\S/.test(row)) return /^locals\s*\{/.test(row)
  }
  return false
}

/** The 1-based column of the declaration's label in its line: the quoted name, or a local's name. */
export function labelColumn(text: string, label: string): number | undefined {
  const quoted = text.lastIndexOf(`"${label}"`)
  if (quoted >= 0) return quoted + 2
  const bare = new RegExp(`^\\s*${label}\\s*=`).exec(text)
  return bare ? text.indexOf(label) + 1 : undefined
}

